#!/bin/bash
# q10jmdp20 = q10jperf6 recipe (q10jfinal2f chain: X list of build_q10jmdp.sh + 0660 GPU step A + 0668 step C without the L2 policy 0664/0667)
#            + 0670 MDP probe + 0671a (stages: probe + DMA self-test S1, no service) + 0673 bring-up stage P + 0674 larb2 SMI bring-up, mutex-eof done, pipe dumps + 0675 larb2 check fix, short log lines + 0676 vendor RDMA/WROT words + WROT line ladder + 0677 WROT rotation offsets + 0678 S2 NV12/RSZ + 0679 AAL2/TDSHP2 sizes + 0680 TDSHP2 enable + 0681 single-tile scale limit + 0682 S2 DIAG scale jobs [piece-0682] + 0672 service (svc default 0) + 0683 + 0684 service ON + 0685 request decoder + 0686 NV12 dst + timing + 0687 service speed + 0688 surface cache/clock log + 0689 per-tile/lockwait timing + S2 TIMING jobs + 0690 dual pipe (RDMA2->WROT2 direct lane, per-pipe locks, pinned caches, S2 DUAL, S3 TIMING + vendor M4U1 write setup, rotation tile choice, per-stream service log) (default 0x103 kern.n2mdp_stages 0x102; was kern.n2mdp_stages 0x101)
B=$NORD2_WORK/gpu/build; M=$NORD2_WORK/gpu/build/mdp-20261114
G="\"0660 $B/gpusched-20261114/piece-0660\" \"0668 $B/gpusched-20261114/piece-0668\" \"0670 $M/piece-0670\" \"0671 $M/piece-0671a\" \"0672 $M/piece-0672\" \"0673 $M/piece-0673\" \"0674 $M/piece-0674\" \"0675 $M/piece-0675\" \"0676 $M/piece-0676\" \"0677 $M/piece-0677\" \"0678 $M/piece-0678\" \"0679 $M/piece-0679\" \"0680 $M/piece-0680\" \"0681 $M/piece-0681\" \"0682 $M/piece-0682\" \"0683 $M/piece-0683\" \"0684 $M/piece-0684\" \"0685 $M/piece-0685\" \"0686 $M/piece-0686\" \"0687 $M/piece-0687\" \"0688 $M/piece-0688\" \"0689 $M/piece-0689\" \"0690 $M/piece-0690\""
GP_MORE="$G" MDP_SCAN="$(cat $M/scan_extra20.txt)" exec bash $M/build_q10jmdp3_base.sh "${1:-q10jmdp20}"
